#include <bits/stdc++.h>using namespace std; int sum_of_digits(long long n) {    int sum = 0;    while (n > 0) {        sum += n % 10;        n /= 10;    }    return sum;}   int main(){    int t;    cin >>t;    while(t--)    {          long long int x;          cin >>x;          if(x%9 == 0)          {               int count = 0;                for (long long y = x; y <= x + 100; y++) {                    if (y - sum_of_digits(y) == x) {                        count++;                    }                }                cout << count << endl;          }          else          {               cout << 0 <<endl;          }    }    return 0;}